-- P99 progression, pinned TAKP implementation. Limits: docs/coldain-ring-nine-audit.md.
local phase = "new"
function event_spawn(e)
  if phase ~= "new" then return end
  phase = "alive"
  e.self:Say("You'll pay with your life for meddling in the affairs of others!")
  -- P99 gives ten minutes to kill her, including time spent fighting.
  eq.set_timer("expire", 600000)
end
function event_timer(e)
  if e.timer == "expire" and phase == "alive" then
    phase = "ended"; eq.stop_timer("expire"); eq.depop()
  end
end
function event_death_complete(e) phase = "ended"; eq.stop_timer("expire") end
